    --frame-width: var(--offer-tab-size, 55px);
    --frame-height: 208px;
    --frame-bottom: calc((100% - var(--frame-height)) / 2);
    background-color: transparent;
  }

  /* lowers z-index on minimized ibm */
  body:has(iframe.overlayHidden) .ab-iam-root.v3 {
